
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_xc_b98_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_b98", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.184215814159122e+00, -2.451534264898620e+00, -2.667517887478926e+00, -2.789000918914974e+00, -2.798080911240688e+00, -2.690966484079194e+00, -2.472014307484735e+00, -2.154741028718524e+00, -1.770713814626002e+00, -1.375244992986975e+00, -9.719177534877006e-01, -6.044325131750521e-01, -5.171760586278862e-01, -4.263886618828878e-01, -3.183904587106156e-01, -2.192226307643128e-01, -1.299622639224539e-01, -4.512873032886050e-02, -9.706924757236864e-03, -1.091948561840059e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


